import axios from 'axios';

const API_BASE_URL = 'http://localhost:8000/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 60000, // Increased timeout to 60 seconds
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor
api.interceptors.request.use(
  (config) => {
    console.log(`Making ${config.method?.toUpperCase()} request to ${config.url}`);
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor
api.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    console.error('API Error:', error.response?.data || error.message);
    return Promise.reject(error);
  }
);

// Upload documents
export const uploadDocuments = async (fileArray) => {
  console.log('API uploadDocuments called with:', fileArray.length, 'files');
  const formData = new FormData();
  fileArray.forEach(file => {
    console.log('Appending to FormData:', file.name, file.type, file.size);
    formData.append('files', file);
  });

  // Log FormData contents for debugging
  console.log('FormData entries:');
  for (let [key, value] of formData.entries()) {
    console.log(key, value);
  }

  try {
    console.log('Making POST request to /upload-documents');
    // Remove Content-Type header to let axios set it with boundary
    const response = await api.post('/upload-documents', formData);
    console.log('API response received:', response);
    return response.data;
  } catch (error) {
    console.error('API upload error:', error);
    console.error('Error response:', error.response);
    console.error('Error config:', error.config);

    // Fallback to fetch if axios fails
    console.log('Trying fallback with fetch...');
    try {
      const fetchResponse = await fetch('http://localhost:8000/api/upload-documents', {
        method: 'POST',
        body: formData,
        mode: 'cors'
      });

      if (!fetchResponse.ok) {
        throw new Error(`HTTP error! status: ${fetchResponse.status}`);
      }

      const data = await fetchResponse.json();
      console.log('Fetch response received:', data);
      return data;
    } catch (fetchError) {
      console.error('Fetch fallback also failed:', fetchError);
      throw fetchError;
    }
  }
};

// Analyze company
export const analyzeCompany = async (documents) => {
  const response = await api.post('/analyze-company', { documents });
  return response.data;
};

// Consistency analysis
export const analyzeConsistency = async (gstData, bankData) => {
